window.__YJ=window.__YJ||{};window.__YJ["asciicn-terminal-window"]={"files":[{"path":"components/terminal-window.tsx","language":"tsx","content":"/**\n * asciicn · terminal-window\n * MIT License · Copyright (c) 2026 Leo; Copyright (c) 2026 Shadcn Labs (startercn)\n * https://asciicn.dev/docs/terminal-window\n * https://github.com/opencoredev/asciicn\n */\n\"use client\";\n\nimport { useLayoutEffect, useRef, useState } from \"react\";\nimport type { CSSProperties, ReactNode } from \"react\";\n\nimport { AsciiBox } from \"@/components/asciicn/ascii-box\";\nimport type {\n  AsciiBoxFrame,\n  AsciiBoxProps,\n} from \"@/components/asciicn/ascii-box\";\nimport { Loader } from \"@/components/asciicn/loader\";\nimport { ProgressBar } from \"@/components/asciicn/progress-bar\";\nimport {\n  CHARSETS,\n  cssColor,\n  rampChar,\n  useFrameLoop,\n  usePrefersReducedMotion,\n} from \"@/lib/ascii\";\nimport type { AsciiColor } from \"@/lib/ascii\";\nimport { cn } from \"@/lib/utils\";\n\n/*\n * The script compiles to a timeline: every step gets a start and an end in\n * seconds. What the window shows is a pure function of one clock, so\n * pausing stops the clock, speed scales it and a loop resets it. The clock\n * only advances while the window is on screen, so a session starts when\n * the visitor scrolls to it.\n */\n\n/** How an output line is coloured, and the mark before it. */\nexport type TerminalTone = \"plain\" | \"muted\" | \"ok\" | \"info\" | \"warn\" | \"error\";\n\n/** How a task ends: the mark that replaces its spinner. */\nexport type TerminalResult = \"ok\" | \"warn\" | \"error\";\n\n/** One step of a scripted session. */\nexport type TerminalStep =\n  | {\n      /** Typed at the prompt one key at a time, then entered. */\n      kind: \"command\";\n      text: string;\n    }\n  | {\n      /** Printed a line at a time. `\\n` starts a new line. */\n      kind: \"output\";\n      text: string;\n      /** Default `\"plain\"`. */\n      tone?: TerminalTone;\n      /** Clip long lines instead of wrapping them, for ASCII art. Default `true`. */\n      wrap?: boolean;\n      /** Read to screen readers instead of `text`, for art. */\n      alt?: string;\n    }\n  | {\n      /** A spinner while it runs, then a result mark. */\n      kind: \"task\";\n      text: string;\n      /** Seconds the spinner runs. Default 1.2. */\n      duration?: number;\n      /** Default `\"ok\"`. */\n      result?: TerminalResult;\n      /** Text once it ends. Default: `text`. */\n      done?: string;\n    }\n  | {\n      /** A block progress bar that fills from 0 to 100%. */\n      kind: \"progress\";\n      label: string;\n      /** Seconds to fill. Default 2. */\n      duration?: number;\n      /** Width of the bar in cells. Default 20. */\n      width?: number;\n    }\n  | {\n      /** A pause with nothing printed. */\n      kind: \"wait\";\n      duration: number;\n    };\n\nexport type TerminalWindowSize = \"sm\" | \"md\" | \"lg\";\n\nexport interface TerminalWindowProps extends Omit<\n  AsciiBoxProps,\n  \"title\" | \"footer\" | \"children\" | \"frame\"\n> {\n  /** The session to play. Default: installing a component with the shadcn CLI, building, and printing a frame. */\n  script?: readonly TerminalStep[];\n  /** Text in the title bar, such as a path or a command. Default `\"~/acme — zsh\"`. */\n  title?: string;\n  /** Playback speed multiplier. Default 1. */\n  speed?: number;\n  /** Start over after a pause at the end. Default `true`. */\n  loop?: boolean;\n  /** Height of the screen in lines; older lines scroll off the top. Default 18. */\n  rows?: number;\n  /** The prompt before each command. Default `\"$\"`. */\n  prompt?: string;\n  /** Box-drawing set for the window frame. Default `\"rounded\"`. */\n  frame?: AsciiBoxFrame;\n  /** Glyph cell height: `sm` 12px, `md` 14px, `lg` 16px. Default `\"lg\"`. */\n  size?: TerminalWindowSize;\n}\n\nconst CELLS = { lg: 16, md: 14, sm: 12 } as const satisfies Record<\n  TerminalWindowSize,\n  number\n>;\n\n/** Seconds at speed 1. */\nconst TIMING = {\n  /** Before the first key of a command. */\n  beforeTyping: 0.45,\n  /** After the last key, before the command runs. */\n  enter: 0.3,\n  /** Holding the finished session before a loop starts over. */\n  hold: 3.5,\n  /** Between keys, before jitter. */\n  key: 0.042,\n  /** Between streamed output lines. */\n  line: 0.05,\n} as const;\n\nconst TONE_COLORS = {\n  error: \"red\",\n  info: \"blue\",\n  muted: \"grey\",\n  ok: \"green\",\n  plain: \"ink\",\n  warn: \"orange\",\n} as const satisfies Record<TerminalTone, AsciiColor>;\n\nconst MARKS = {\n  error: \"✖\",\n  info: \"›\",\n  muted: \"\",\n  ok: \"✔\",\n  plain: \"\",\n  warn: \"!\",\n} as const satisfies Record<TerminalTone, string>;\n\n/** A torus at a fixed angle, shaded with the `standard` ramp, for the default script to print. */\nconst torusFrame = (columns: number, rows: number): string => {\n  const tones = new Float32Array(columns * rows);\n  const depth = new Float32Array(columns * rows);\n  // Tipped about one radian towards the viewer, so the hole shows.\n  const [ct, st] = [Math.cos(1), Math.sin(1)];\n  // Light from above and in front.\n  const [ly, lz] = [Math.SQRT1_2, -Math.SQRT1_2];\n  // Projected size in cells; cells are about twice as tall as wide.\n  const scale = columns * 0.8;\n  for (let a = 0; a < Math.PI * 2; a += 0.04) {\n    const [ca, sa] = [Math.cos(a), Math.sin(a)];\n    for (let b = 0; b < Math.PI * 2; b += 0.015) {\n      const [cb, sb] = [Math.cos(b), Math.sin(b)];\n      // A point on the tube (radius 0.7) around the ring (radius 2), and its normal.\n      const ring = 2 + 0.7 * ca;\n      const [x, y0, z0] = [ring * cb, 0.7 * sa, ring * sb];\n      const [ny0, nz0] = [sa, ca * sb];\n      const [y, z] = [y0 * ct - z0 * st, y0 * st + z0 * ct];\n      const [ny, nz] = [ny0 * ct - nz0 * st, ny0 * st + nz0 * ct];\n      const inverse = 1 / (z + 7);\n      const column = Math.round(columns / 2 - 0.5 + scale * x * inverse);\n      const row = Math.round(rows / 2 - 0.5 - scale * 0.5 * y * inverse);\n      const index = row * columns + column;\n      const inside = column >= 0 && column < columns && row >= 0 && row < rows;\n      if (inside && inverse > (depth[index] ?? 0)) {\n        depth[index] = inverse;\n        tones[index] = Math.max(0.1, ny * ly + nz * lz);\n      }\n    }\n  }\n  const lines: string[] = [];\n  for (let row = 0; row < rows; row += 1) {\n    let line = \"\";\n    for (let column = 0; column < columns; column += 1) {\n      const index = row * columns + column;\n      line +=\n        (depth[index] ?? 0) > 0\n          ? rampChar(CHARSETS.standard, tones[index] ?? 0)\n          : \" \";\n    }\n    lines.push(line.trimEnd());\n  }\n  return lines.filter((line) => line !== \"\").join(\"\\n\");\n};\n\n/** Installs a component, builds, and prints a frame with the engine. */\nexport const DEFAULT_TERMINAL_SCRIPT: readonly TerminalStep[] = [\n  {\n    kind: \"command\",\n    text: \"npx shadcn@latest add https://asciicn.dev/r/ascii-donut.json\",\n  },\n  {\n    done: \"Registry timed out, retrying (1/3)\",\n    duration: 1.1,\n    kind: \"task\",\n    result: \"error\",\n    text: \"Checking registry.\",\n  },\n  { duration: 0.8, kind: \"task\", text: \"Checking registry.\" },\n  { duration: 1.9, kind: \"progress\", label: \"Installing dependencies\" },\n  { kind: \"output\", text: \"Created 3 files:\", tone: \"ok\" },\n  {\n    kind: \"output\",\n    text: \"  - components/asciicn/ascii-donut.tsx\\n  - lib/ascii/index.ts\\n  - lib/ascii/shader.tsx\",\n    tone: \"muted\",\n  },\n  {\n    kind: \"output\",\n    text: \"Kept styles/globals.css: --ascii-* tokens already set\",\n    tone: \"warn\",\n  },\n  { kind: \"command\", text: \"pnpm build\" },\n  {\n    done: \"Compiled in 3.8s\",\n    duration: 1.6,\n    kind: \"task\",\n    text: \"Compiling\",\n  },\n  {\n    done: \"Prerendered 14 pages\",\n    duration: 0.9,\n    kind: \"task\",\n    text: \"Prerendering pages\",\n  },\n  { kind: \"command\", text: \"npx tsx scripts/frame.ts --charset standard\" },\n  { duration: 0.35, kind: \"wait\" },\n  {\n    alt: \"A torus drawn in ASCII characters.\",\n    kind: \"output\",\n    text: `\\n${torusFrame(32, 12)}\\n`,\n    wrap: false,\n  },\n  {\n    kind: \"output\",\n    text: \"frame 1 · 32×12 cells · standard · 2.4 ms\",\n    tone: \"muted\",\n  },\n];\n\n/** A stable 0..1 jitter per key, so typing has a human rhythm that repeats exactly. */\nconst jitter = (index: number) => {\n  const x = Math.sin(index * 12.9898 + 78.233) * 43_758.5453;\n  return x - Math.floor(x);\n};\n\n/** Seconds from the first key to each key of `text`, at speed 1. */\nconst keyTimes = (text: string): number[] => {\n  const times: number[] = [];\n  let at = 0;\n  for (const [index, char] of [...text].entries()) {\n    at += TIMING.key * (0.55 + jitter(index) * 0.9);\n    // A beat after a space or a slash, as fingers find the next word.\n    if (char === \" \" || char === \"/\") {\n      at += TIMING.key * 1.2;\n    }\n    times.push(at);\n  }\n  return times;\n};\n\ninterface Timed {\n  readonly step: TerminalStep;\n  readonly start: number;\n  readonly end: number;\n  /** For commands: when each key lands, from the step's start. */\n  readonly keys: readonly number[];\n}\n\ninterface Timeline {\n  readonly steps: readonly Timed[];\n  readonly total: number;\n}\n\nconst stepLength = (step: TerminalStep, keys: readonly number[]): number => {\n  switch (step.kind) {\n    case \"command\": {\n      return TIMING.beforeTyping + (keys.at(-1) ?? 0) + TIMING.enter;\n    }\n    case \"output\": {\n      return (step.text.split(\"\\n\").length + 1) * TIMING.line;\n    }\n    case \"task\": {\n      return step.duration ?? 1.2;\n    }\n    case \"progress\": {\n      return step.duration ?? 2;\n    }\n    case \"wait\": {\n      return step.duration;\n    }\n    default: {\n      const exhaustive: never = step;\n      return exhaustive;\n    }\n  }\n};\n\nconst compile = (script: readonly TerminalStep[]): Timeline => {\n  let at = 0;\n  const steps = script.map((step) => {\n    const keys = step.kind === \"command\" ? keyTimes(step.text) : [];\n    const start = at;\n    at += Math.max(0, stepLength(step, keys));\n    return { end: at, keys, start, step };\n  });\n  return { steps, total: at };\n};\n\n/** One line on the screen. */\ntype Line =\n  | { kind: \"command\"; text: string; typing: boolean }\n  | { kind: \"output\"; text: string; tone: TerminalTone; wrap: boolean }\n  | { kind: \"task\"; text: string; state: \"running\" | TerminalResult }\n  | { kind: \"progress\"; label: string; value: number; width: number };\n\ninterface Screen {\n  readonly lines: readonly Line[];\n  /** The session is over: an idle prompt waits at the bottom. */\n  readonly idle: boolean;\n}\n\n/** Progress that stalls and spurts like a real install, still always rising. */\nconst progressAt = (t: number) =>\n  Math.min(1, Math.max(0, t - 0.035 * Math.sin(t * Math.PI * 3)));\n\nconst linesOf = (timed: Timed, time: number): Line[] => {\n  const { step, start, end } = timed;\n  const local = time - start;\n  switch (step.kind) {\n    case \"command\": {\n      const typed = timed.keys.filter(\n        (at) => at <= local - TIMING.beforeTyping\n      ).length;\n      return [\n        {\n          kind: \"command\",\n          text: [...step.text].slice(0, typed).join(\"\"),\n          typing: time < end,\n        },\n      ];\n    }\n    case \"output\": {\n      const shown = Math.floor(local / TIMING.line) + 1;\n      return step.text\n        .split(\"\\n\")\n        .slice(0, shown)\n        .map((text) => ({\n          kind: \"output\",\n          text,\n          tone: step.tone ?? \"plain\",\n          wrap: step.wrap ?? true,\n        }));\n    }\n    case \"task\": {\n      const over = time >= end;\n      return [\n        {\n          kind: \"task\",\n          state: over ? (step.result ?? \"ok\") : \"running\",\n          text: over ? (step.done ?? step.text) : step.text,\n        },\n      ];\n    }\n    case \"progress\": {\n      const length = end - start;\n      return [\n        {\n          kind: \"progress\",\n          label: step.label,\n          value: length > 0 ? progressAt(local / length) * 100 : 100,\n          width: step.width ?? 20,\n        },\n      ];\n    }\n    case \"wait\": {\n      return [];\n    }\n    default: {\n      const exhaustive: never = step;\n      return exhaustive;\n    }\n  }\n};\n\n/** The screen at `time` seconds into the session. */\nconst screenAt = (timeline: Timeline, time: number): Screen => ({\n  idle: time >= timeline.total,\n  lines: timeline.steps\n    .filter((timed) => timed.start <= time)\n    .flatMap((timed) => linesOf(timed, time)),\n});\n\n/** Changes exactly when what the screen draws changes, so the clock can skip renders. */\nconst screenKey = (screen: Screen): string =>\n  `${screen.idle ? 1 : 0}|${screen.lines\n    .map((line) => {\n      switch (line.kind) {\n        case \"command\": {\n          return `${line.text.length}${line.typing ? \"t\" : \"\"}`;\n        }\n        case \"task\": {\n          return line.state;\n        }\n        case \"progress\": {\n          // An eighth of a cell is the smallest step the bar can draw.\n          return String(Math.round((line.value / 100) * line.width * 8));\n        }\n        case \"output\": {\n          return \"o\";\n        }\n        default: {\n          const exhaustive: never = line;\n          return exhaustive;\n        }\n      }\n    })\n    .join(\",\")}`;\n\n/** The whole session as plain lines, for screen readers. */\nconst transcript = (\n  script: readonly TerminalStep[],\n  prompt: string\n): string[] =>\n  script.flatMap((step) => {\n    switch (step.kind) {\n      case \"command\": {\n        return [`${prompt} ${step.text}`];\n      }\n      case \"output\": {\n        // Art reads as noise, so `alt` can say what it is instead.\n        return step.alt === undefined\n          ? step.text.split(\"\\n\").map((line) => line.trim())\n          : [step.alt];\n      }\n      case \"task\": {\n        return [step.done ?? step.text];\n      }\n      case \"progress\": {\n        return [`${step.label}: done`];\n      }\n      case \"wait\": {\n        return [];\n      }\n      default: {\n        const exhaustive: never = step;\n        return exhaustive;\n      }\n    }\n  });\n\n/** A block cursor; it holds solid while keys land and blinks at rest. */\nconst Cursor = ({ blink }: { blink: boolean }) => (\n  <span\n    aria-hidden=\"true\"\n    className={cn(\n      \"inline-block w-[1ch] bg-[var(--term-ink)] align-top\",\n      blink && \"motion-safe:animate-[term-blink_1.06s_steps(1,end)_infinite]\"\n    )}\n    style={{ height: \"var(--term-cell)\" }}\n  />\n);\n\nconst Mark = ({ tone }: { tone: TerminalTone }) =>\n  MARKS[tone] ? (\n    <span\n      className=\"inline-block w-[2ch] shrink-0\"\n      style={{ color: cssColor(TONE_COLORS[tone]) }}\n    >\n      {MARKS[tone]}\n    </span>\n  ) : null;\n\nconst ScreenLine = ({\n  line,\n  prompt,\n  cell,\n}: {\n  line: Line;\n  prompt: string;\n  cell: number;\n}) => {\n  switch (line.kind) {\n    case \"command\": {\n      return (\n        <div className=\"break-words whitespace-pre-wrap\">\n          <span style={{ color: cssColor(\"green\") }}>{prompt} </span>\n          <span className=\"text-[var(--term-ink)]\">{line.text}</span>\n          {line.typing ? <Cursor blink={false} /> : null}\n        </div>\n      );\n    }\n    case \"output\": {\n      const color =\n        line.tone === \"warn\" || line.tone === \"error\" || line.tone === \"muted\"\n          ? cssColor(TONE_COLORS[line.tone])\n          : \"var(--term-ink)\";\n      return (\n        <div\n          className={cn(\n            \"flex\",\n            line.wrap\n              ? \"break-words whitespace-pre-wrap\"\n              : \"overflow-hidden whitespace-pre\"\n          )}\n        >\n          <Mark tone={line.tone} />\n          <span className=\"min-w-0\" style={{ color }}>\n            {line.text || \" \"}\n          </span>\n        </div>\n      );\n    }\n    case \"task\": {\n      return (\n        <div className=\"flex whitespace-pre-wrap\">\n          <span className=\"inline-flex w-[2ch] shrink-0\">\n            {line.state === \"running\" ? (\n              <Loader\n                label={line.text}\n                spinner=\"orbit\"\n                color=\"blue\"\n                cell={cell}\n              />\n            ) : (\n              <Mark tone={line.state} />\n            )}\n          </span>\n          <span\n            className=\"min-w-0 break-words\"\n            style={{\n              color:\n                line.state === \"error\" || line.state === \"warn\"\n                  ? cssColor(TONE_COLORS[line.state])\n                  : undefined,\n            }}\n          >\n            {line.text}\n          </span>\n        </div>\n      );\n    }\n    case \"progress\": {\n      const percent = Math.floor(line.value);\n      return (\n        <div className=\"flex flex-wrap items-center gap-x-[1ch]\">\n          <span className=\"inline-flex items-center\">\n            <span>[</span>\n            <span className=\"inline-grid\">\n              <ProgressBar\n                label={line.label}\n                hideLabel\n                value={line.value}\n                columns={line.width}\n                // ProgressBar sets its glyphs at cell / 1.17; this lands them\n                // at the terminal's cell / 1.2, so the bar sits on its grid.\n                cell={(cell * 1.17) / 1.2}\n                color=\"ink\"\n                animate={false}\n              />\n            </span>\n            <span>]</span>\n          </span>\n          <span className=\"w-[4ch] text-right tabular-nums\">{`${percent}%`}</span>\n          <span style={{ color: cssColor(\"grey\") }}>{line.label}</span>\n        </div>\n      );\n    }\n    default: {\n      const exhaustive: never = line;\n      return exhaustive;\n    }\n  }\n};\n\ntype PlayState = \"playing\" | \"paused\" | \"done\";\n\nconst PLAY_LABELS = {\n  done: { glyph: \"↻\", text: \"Replay\" },\n  paused: { glyph: \"▶\", text: \"Play\" },\n  playing: { glyph: \"‖\", text: \"Pause\" },\n} as const satisfies Record<PlayState, { glyph: string; text: string }>;\n\n/** The terminal's CSS variables: cell height and text ink. */\ntype TerminalVars = CSSProperties &\n  Record<\"--term-cell\" | \"--term-ink\", string>;\n\n/**\n * A terminal window framed in box-drawing glyphs that plays a scripted\n * session: commands typed key by key, output streamed line by line,\n * spinners from `Loader`, block bars from `ProgressBar`, coloured ok, warn\n * and error lines, and a blinking cursor at the final prompt. It starts\n * when scrolled into view, has a pause button in its bottom border, and\n * shows the finished session as one still frame under reduced motion.\n */\nexport const TerminalWindow = ({\n  script = DEFAULT_TERMINAL_SCRIPT,\n  title = \"~/acme — zsh\",\n  speed = 1,\n  loop = true,\n  rows = 18,\n  prompt = \"$\",\n  frame = \"rounded\",\n  size = \"lg\",\n  cell,\n  color = \"grey\",\n  className,\n  style,\n  ...props\n}: TerminalWindowProps) => {\n  const screenRef = useRef<HTMLDivElement>(null);\n  const reduced = usePrefersReducedMotion();\n  const height = cell ?? CELLS[size];\n  const timeline = compile(script);\n  const [play, setPlay] = useState<PlayState>(\"playing\");\n  const [time, setTime] = useState(0);\n  const clock = useRef(0);\n  const shownKey = useRef(\"\");\n\n  useFrameLoop(\n    (_time, delta) => {\n      const next = clock.current + delta * Math.max(0, speed);\n      if (next >= timeline.total + TIMING.hold && timeline.total > 0) {\n        if (loop) {\n          clock.current = 0;\n          shownKey.current = \"\";\n          setTime(0);\n        } else {\n          clock.current = timeline.total;\n          setTime(timeline.total);\n          setPlay(\"done\");\n        }\n        return;\n      }\n      clock.current = next;\n      // Render only when the screen would change, not on every tick.\n      const key = screenKey(screenAt(timeline, next));\n      if (key !== shownKey.current) {\n        shownKey.current = key;\n        setTime(next);\n      }\n    },\n    { enabled: play === \"playing\", fps: 30, target: screenRef }\n  );\n\n  // Under reduced motion the session is one still frame: the end.\n  const shown = reduced ? timeline.total : time;\n  const screen = screenAt(timeline, shown);\n\n  // New lines push old ones off the top, as in a real terminal.\n  const lineCount = screen.lines.length;\n  useLayoutEffect(() => {\n    const el = screenRef.current;\n    if (el && lineCount >= 0) {\n      el.scrollTop = el.scrollHeight;\n    }\n  }, [lineCount, shown]);\n\n  const toggle = () => {\n    if (play === \"done\") {\n      clock.current = 0;\n      shownKey.current = \"\";\n      setTime(0);\n      setPlay(\"playing\");\n      return;\n    }\n    setPlay(play === \"playing\" ? \"paused\" : \"playing\");\n  };\n\n  const vars: TerminalVars = {\n    \"--term-cell\": `${height}px`,\n    \"--term-ink\": \"var(--ascii-ink)\",\n    ...style,\n  };\n  const textStyle: CSSProperties = {\n    fontFamily: \"var(--ascii-font, monospace)\",\n    fontSize: `${height / 1.2}px`,\n    fontVariantLigatures: \"none\",\n    height: `${rows * height}px`,\n    letterSpacing: 0,\n    lineHeight: `${height}px`,\n  };\n  const control = PLAY_LABELS[play];\n\n  const titleBar: ReactNode = (\n    <span className=\"inline-flex items-baseline gap-[1ch]\">\n      <span aria-hidden=\"true\" className=\"tracking-[0.1em]\">\n        <span style={{ color: cssColor(\"red\") }}>●</span>\n        <span style={{ color: cssColor(\"orange\") }}>●</span>\n        <span style={{ color: cssColor(\"green\") }}>●</span>\n      </span>\n      <span>{title}</span>\n    </span>\n  );\n\n  const footer: ReactNode = reduced ? null : (\n    <button\n      type=\"button\"\n      onClick={toggle}\n      aria-label={`${control.text} the terminal session`}\n      className=\"pointer-events-auto cursor-pointer px-[1ch] text-muted-foreground outline-hidden select-none hover:text-foreground focus-visible:bg-[var(--ascii-ink)] focus-visible:text-[var(--ascii-paper)]\"\n    >\n      {`${control.glyph} ${control.text.toLowerCase()}`}\n    </button>\n  );\n\n  return (\n    <AsciiBox\n      data-slot=\"terminal-window\"\n      frame={frame}\n      title={titleBar}\n      footer={footer}\n      color={color}\n      cell={height}\n      className={cn(\"w-full\", className)}\n      style={vars}\n      {...props}\n    >\n      <style>{\"@keyframes term-blink{0%{opacity:1}50%{opacity:0}}\"}</style>\n      <div\n        ref={screenRef}\n        aria-hidden=\"true\"\n        className=\"overflow-hidden text-[var(--term-ink)]\"\n        style={textStyle}\n      >\n        {screen.lines.map((line, index) => (\n          // Lines are positional: the nth line of the session.\n          // oxlint-disable-next-line react/no-array-index-key\n          <ScreenLine key={index} line={line} prompt={prompt} cell={height} />\n        ))}\n        {screen.idle ? (\n          <div>\n            <span style={{ color: cssColor(\"green\") }}>{prompt} </span>\n            <Cursor blink />\n          </div>\n        ) : null}\n      </div>\n      <div className=\"sr-only\">\n        {transcript(script, prompt).map((line, index) => (\n          // oxlint-disable-next-line react/no-array-index-key\n          <p key={index}>{line}</p>\n        ))}\n      </div>\n    </AsciiBox>\n  );\n};\n"},{"path":"components/ascii-box.tsx","language":"tsx","content":"\"use client\";\n\nimport { useId, useLayoutEffect, useRef } from \"react\";\nimport type { ComponentProps, CSSProperties, ReactNode } from \"react\";\n\nimport { BOX, cssColor } from \"@/lib/ascii\";\nimport type { AsciiColor, BoxStyle } from \"@/lib/ascii\";\nimport { cn } from \"@/lib/utils\";\n\n/*\n * The frame is real box-drawing text in a 3x3 grid: one cell for each\n * corner and side, with the sides as long runs of glyphs clipped to fit.\n * After mount the box measures its content, rounds its own size up to\n * whole cells and pins it, so every glyph of the frame lands on the cell\n * grid and the corners join the sides exactly. Before that (and on the\n * server) the clipped runs still draw a closed frame, so nothing jumps.\n */\n\n/** Frame glyph sets, from `BOX` in the engine. */\nexport const ASCII_BOX_FRAMES = [\n  \"light\",\n  \"heavy\",\n  \"double\",\n  \"rounded\",\n  \"ascii\",\n] as const satisfies readonly BoxStyle[];\n\nexport type AsciiBoxFrame = (typeof ASCII_BOX_FRAMES)[number];\n\n/** Shade glyphs for the drop shadow, from light to dark. */\nexport const ASCII_BOX_SHADOWS = {\n  dark: \"▓\",\n  light: \"░\",\n  medium: \"▒\",\n} as const;\n\nexport type AsciiBoxShadow = keyof typeof ASCII_BOX_SHADOWS;\n\nexport type AsciiBoxLabelAlign = \"start\" | \"center\" | \"end\";\n\n/** Long enough for any side; the overflow is clipped. */\nconst RUN = 320;\n\n// Glyph cell width per cell height before the font is measured: 0.6em\n// advance over a 1.2em line, as `measureCell` assumes.\nconst FALLBACK_WIDTH = \"calc(var(--box-ch) * 0.5)\";\n\nexport interface AsciiBoxProps extends Omit<ComponentProps<\"div\">, \"title\"> {\n  /** Box-drawing set for the frame. Default `\"light\"`. */\n  frame?: AsciiBoxFrame;\n  /** A label set into the top border, as in `┌─ Title ───┐`. Also names the box for screen readers. */\n  title?: ReactNode;\n  /** A label set into the bottom border, such as a status or a count. */\n  footer?: ReactNode;\n  /** Where the labels sit along their border. Default `\"start\"`. */\n  labelAlign?: AsciiBoxLabelAlign;\n  /** A shade-glyph drop shadow one cell right and one row down. Default `false` (none). */\n  shadow?: boolean | AsciiBoxShadow;\n  /** Frame colour: a palette name, a CSS variable name or any CSS colour. Default `\"ink\"`. */\n  color?: AsciiColor;\n  /** Space between the frame and the content in rows; columns are doubled so both read the same. Default 1. */\n  padding?: number;\n  /** Cell height in CSS pixels. Default `--ascii-cell`, or 12. */\n  cell?: number;\n  /** Paint `--ascii-paper` inside the frame, so the box hides what sits behind it. Default `false`. */\n  filled?: boolean;\n  /** Decoration drawn inside the frame and behind the content, such as `AsciiGlow`. It fills the inner cells. */\n  backdrop?: ReactNode;\n}\n\n/** The box's CSS variables: cell height, cell width and frame colour. */\ntype BoxVars = CSSProperties &\n  Record<\"--box-ch\" | \"--box-cw\" | \"--box-ink\", string>;\n\ninterface Glyphs {\n  readonly tl: string;\n  readonly tr: string;\n  readonly bl: string;\n  readonly br: string;\n  readonly h: string;\n  readonly v: string;\n}\n\n/**\n * The content width of the nearest box around the box's wrapper: the most\n * the box may take. `display: contents` ancestors have no box, so skip them.\n */\nconst roomFor = (wrapper: HTMLElement | null): number => {\n  let outer = wrapper?.parentElement ?? null;\n  while (outer && getComputedStyle(outer).display === \"contents\") {\n    outer = outer.parentElement;\n  }\n  if (!outer) {\n    return Number.POSITIVE_INFINITY;\n  }\n  const computed = getComputedStyle(outer);\n  return (\n    outer.clientWidth -\n    (Number.parseFloat(computed.paddingLeft) || 0) -\n    (Number.parseFloat(computed.paddingRight) || 0)\n  );\n};\n\nconst verticalRun = (glyph: string) => `${glyph}\\n`.repeat(RUN / 4);\n\nconst Label = ({\n  id,\n  glyph,\n  align,\n  children,\n}: {\n  id?: string;\n  glyph: string;\n  align: AsciiBoxLabelAlign;\n  children: ReactNode;\n}) => {\n  const run = glyph.repeat(RUN);\n  return (\n    <div className=\"flex min-w-0 overflow-hidden\">\n      <span\n        aria-hidden=\"true\"\n        className={cn(\n          \"overflow-hidden\",\n          align === \"start\"\n            ? \"w-[var(--box-cw)] shrink-0\"\n            : \"min-w-[var(--box-cw)] flex-1\"\n        )}\n      >\n        {run}\n      </span>\n      <span\n        id={id}\n        data-slot=\"ascii-box-label\"\n        className=\"min-w-0 truncate px-[var(--box-cw)] text-foreground\"\n      >\n        {children}\n      </span>\n      <span\n        aria-hidden=\"true\"\n        className={cn(\n          \"overflow-hidden\",\n          align === \"end\"\n            ? \"w-[var(--box-cw)] shrink-0\"\n            : \"min-w-[var(--box-cw)] flex-1\"\n        )}\n      >\n        {run}\n      </span>\n    </div>\n  );\n};\n\nconst Edge = ({\n  glyph,\n  label,\n  labelId,\n  align,\n}: {\n  glyph: string;\n  label: ReactNode;\n  labelId?: string;\n  align: AsciiBoxLabelAlign;\n}) =>\n  label === undefined || label === null || label === false ? (\n    <div aria-hidden=\"true\" className=\"overflow-hidden\">\n      {glyph.repeat(RUN)}\n    </div>\n  ) : (\n    <Label id={labelId} glyph={glyph} align={align}>\n      {label}\n    </Label>\n  );\n\n/**\n * Wraps any content in a box-drawing frame that sizes to the content on\n * the glyph cell grid: `light`, `heavy`, `double`, `rounded` or `ascii`\n * borders, labels set into the top and bottom borders, and an optional\n * shade-glyph shadow. The primitive the other asciicn interface pieces\n * are built on.\n */\nexport const AsciiBox = ({\n  frame = \"light\",\n  title,\n  footer,\n  labelAlign = \"start\",\n  shadow = false,\n  color = \"ink\",\n  padding = 1,\n  cell,\n  filled = false,\n  backdrop,\n  className,\n  style,\n  children,\n  ...props\n}: AsciiBoxProps) => {\n  const boxRef = useRef<HTMLDivElement>(null);\n  const contentRef = useRef<HTMLDivElement>(null);\n  const probeRef = useRef<HTMLSpanElement>(null);\n  const titleId = useId();\n  const glyphs: Glyphs = BOX[frame];\n  const shade =\n    shadow === false\n      ? null\n      : ASCII_BOX_SHADOWS[shadow === true ? \"light\" : shadow];\n  const hasTitle = title !== undefined && title !== null && title !== false;\n  const pad = Math.max(0, padding);\n\n  // Snap the box to whole cells whenever it or its content changes size.\n  useLayoutEffect(() => {\n    const box = boxRef.current;\n    const content = contentRef.current;\n    const probe = probeRef.current;\n    if (!(box && content && probe)) {\n      return;\n    }\n    const snap = () => {\n      const run = probe.getBoundingClientRect();\n      const width = run.width / 10;\n      const { height } = run;\n      if (!(width > 0 && height > 0)) {\n        return;\n      }\n      box.style.setProperty(\"--box-cw\", `${width}px`);\n      // Measure the natural size with nothing pinned, then pin whole cells.\n      box.style.width = \"\";\n      box.style.height = \"\";\n      const natural = box.getBoundingClientRect();\n      const room = roomFor(box.parentElement) - (shade ? width : 0);\n      // Round up, unless that would overflow the parent: then round down.\n      let columns = Math.ceil(natural.width / width - 0.01);\n      if (columns * width > room + 0.5) {\n        columns = Math.max(2, Math.floor(natural.width / width + 0.01));\n      }\n      const rows = Math.max(2, Math.ceil(natural.height / height - 0.01));\n      box.style.width = `${columns * width}px`;\n      box.style.height = `${rows * height}px`;\n      box.dataset.columns = String(columns);\n      box.dataset.rows = String(rows);\n    };\n    snap();\n    const resize = new ResizeObserver(snap);\n    resize.observe(content);\n    // The wrapper follows its container's width, so it reports when the room changes.\n    if (box.parentElement) {\n      resize.observe(box.parentElement);\n    }\n    // Text that grows without changing the content's height still needs a new width.\n    const mutations = new MutationObserver(snap);\n    mutations.observe(content, {\n      characterData: true,\n      childList: true,\n      subtree: true,\n    });\n    document.fonts?.addEventListener?.(\"loadingdone\", snap);\n    return () => {\n      resize.disconnect();\n      mutations.disconnect();\n      document.fonts?.removeEventListener?.(\"loadingdone\", snap);\n    };\n  }, [shade, cell, pad, frame]);\n\n  const vars: BoxVars = {\n    \"--box-ch\": cell === undefined ? \"var(--ascii-cell, 12px)\" : `${cell}px`,\n    \"--box-cw\": FALLBACK_WIDTH,\n    \"--box-ink\": cssColor(color),\n  };\n\n  return (\n    <div\n      data-slot=\"ascii-box\"\n      role={hasTitle ? \"group\" : undefined}\n      aria-labelledby={hasTitle ? titleId : undefined}\n      className={cn(\n        \"relative w-fit max-w-full\",\n        shade && \"pr-[var(--box-cw)] pb-[var(--box-ch)]\",\n        className\n      )}\n      style={{ ...vars, ...style }}\n      {...props}\n    >\n      <div\n        ref={boxRef}\n        data-frame={frame}\n        className=\"relative max-w-full\"\n        style={{\n          padding: `calc(var(--box-ch) * ${1 + pad}) calc(var(--box-cw) * ${1 + pad * 2})`,\n        }}\n      >\n        {filled ? (\n          <div\n            aria-hidden=\"true\"\n            className=\"absolute inset-[calc(var(--box-ch)/2)_calc(var(--box-cw)/2)] bg-[var(--ascii-paper)]\"\n          />\n        ) : null}\n        {backdrop ? (\n          <div\n            aria-hidden=\"true\"\n            className=\"pointer-events-none absolute inset-[var(--box-ch)_var(--box-cw)] overflow-hidden\"\n          >\n            {backdrop}\n          </div>\n        ) : null}\n        <div className=\"pointer-events-none absolute inset-0 grid grid-cols-[var(--box-cw)_minmax(0,1fr)_var(--box-cw)] grid-rows-[var(--box-ch)_minmax(0,1fr)_var(--box-ch)] font-[family-name:var(--ascii-font,ui-monospace,monospace)] text-[var(--box-ink)] whitespace-pre select-none [font-size:calc(var(--box-ch)/1.17)] [font-variant-ligatures:none] leading-[var(--box-ch)]\">\n          <span aria-hidden=\"true\">{glyphs.tl}</span>\n          <Edge\n            glyph={glyphs.h}\n            label={title}\n            labelId={titleId}\n            align={labelAlign}\n          />\n          <span aria-hidden=\"true\">{glyphs.tr}</span>\n          <div aria-hidden=\"true\" className=\"overflow-hidden\">\n            {verticalRun(glyphs.v)}\n          </div>\n          <span\n            aria-hidden=\"true\"\n            ref={probeRef}\n            className=\"invisible absolute top-0 left-0\"\n          >\n            {glyphs.h.repeat(10)}\n          </span>\n          <div aria-hidden=\"true\" className=\"col-start-3 overflow-hidden\">\n            {verticalRun(glyphs.v)}\n          </div>\n          <span aria-hidden=\"true\">{glyphs.bl}</span>\n          <Edge glyph={glyphs.h} label={footer} align={labelAlign} />\n          <span aria-hidden=\"true\">{glyphs.br}</span>\n        </div>\n        <div ref={contentRef} className=\"relative min-w-0\">\n          {children}\n        </div>\n      </div>\n      {shade ? (\n        <div\n          aria-hidden=\"true\"\n          className=\"pointer-events-none absolute top-[var(--box-ch)] right-0 bottom-0 left-[var(--box-cw)] font-[family-name:var(--ascii-font,ui-monospace,monospace)] text-[var(--box-ink)] whitespace-pre opacity-70 select-none [font-size:calc(var(--box-ch)/1.17)] leading-[var(--box-ch)]\"\n        >\n          <div className=\"absolute top-0 right-0 bottom-0 w-[var(--box-cw)] overflow-hidden\">\n            {verticalRun(shade)}\n          </div>\n          <div className=\"absolute right-0 bottom-0 left-0 h-[var(--box-ch)] overflow-hidden\">\n            {shade.repeat(RUN)}\n          </div>\n        </div>\n      ) : null}\n    </div>\n  );\n};\n"},{"path":"components/loader.tsx","language":"tsx","content":"\"use client\";\n\nimport { useRef } from \"react\";\nimport type { ComponentProps, CSSProperties } from \"react\";\n\nimport {\n  BRAILLE_DOT_BITS,\n  brailleChar,\n  cssColor,\n  EIGHTHS_UP,\n  SPINNERS,\n  useFrameLoop,\n} from \"@/lib/ascii\";\nimport type { AsciiColor, SpinnerName } from \"@/lib/ascii\";\nimport { cn } from \"@/lib/utils\";\n\n/**\n * Font size per cell height for DOM glyphs. Cascadia Mono's full block and\n * box lines are 1.17em tall, so at this size blocks and lines in\n * neighbouring rows touch instead of leaving a hairline between them.\n */\nconst GLYPH_EM = 1.17;\n\n/**\n * A hairline stroke in the text colour. Adjacent block glyphs meet at\n * fractional pixels, where anti-aliasing leaves a faint seam; the stroke\n * covers it without visibly thickening the glyphs.\n */\nconst SEAL = { WebkitTextStroke: \"0.045em currentColor\" } as const;\n\n/**\n * `spinner` cycles one glyph through a `SPINNERS` sequence, `dots` walks a\n * bright dot along three, `wave` rolls eighth blocks like an equaliser and\n * `comet` sends a Braille comet across six cells.\n */\nexport type LoaderVariant = \"spinner\" | \"dots\" | \"wave\" | \"comet\";\n\nexport type LoaderSize = \"sm\" | \"md\" | \"lg\";\n\nexport interface LoaderProps extends Omit<\n  ComponentProps<\"span\">,\n  \"children\" | \"color\"\n> {\n  /** What is loading, announced politely to screen readers. Default `\"Loading\"`. */\n  label?: string;\n  /** Show the label as text next to the glyphs. Default false. */\n  showLabel?: boolean;\n  /** The animation. Default `\"spinner\"`. */\n  variant?: LoaderVariant;\n  /** For `variant=\"spinner\"`: which glyph sequence. Default `\"orbit\"`. */\n  spinner?: SpinnerName;\n  /** Glyph cell height: `sm` 12px, `md` 16px, `lg` 24px. Default `\"md\"`. */\n  size?: LoaderSize;\n  /** Glyph colour: a palette name or any CSS colour, such as `\"currentColor\"`. Default `\"ink\"`. */\n  color?: AsciiColor;\n  /** Playback speed multiplier. Default 1. */\n  speed?: number;\n  /** Glyph cell height in CSS pixels. Overrides `size`. */\n  cell?: number;\n}\n\nconst CELLS = { lg: 24, md: 16, sm: 12 } as const satisfies Record<\n  LoaderSize,\n  number\n>;\n\n/** Frames per second of each variant at speed 1, and its width in cells. */\nconst TIMING = {\n  comet: { cells: 6, rate: 28 },\n  dots: { cells: 3, rate: 6 },\n  spinner: { cells: 1, rate: 11 },\n  wave: { cells: 6, rate: 24 },\n} as const satisfies Record<LoaderVariant, { cells: number; rate: number }>;\n\nconst DOT_GLYPHS = [\"·\", \"•\", \"●\"] as const;\n\n/** Dots: a bright dot steps along, the one it just left still half lit. */\nconst dotsFrame = (frame: number): string => {\n  const head = frame % 4;\n  let out = \"\";\n  for (let index = 0; index < 3; index += 1) {\n    let level = 0;\n    if (index === head) {\n      level = 2;\n    } else if (index === head - 1) {\n      level = 1;\n    }\n    out += DOT_GLYPHS[level];\n  }\n  return out;\n};\n\n/** Wave: each column rides a sine one step behind its left neighbour. */\nconst waveFrame = (frame: number, cells: number): string => {\n  let out = \"\";\n  for (let index = 0; index < cells; index += 1) {\n    const phase = (frame / 24 - index / 7) * Math.PI * 2;\n    const level = 1 + Math.round(((Math.sin(phase) + 1) / 2) * 7);\n    out += EIGHTHS_UP[level] ?? \"▄\";\n  }\n  return out;\n};\n\n/** Dots lit per Braille column, from the comet's head back along its tail. */\nconst COMET_TAIL = [4, 4, 3, 2, 2, 1, 1, 1] as const;\n/** Which rows a column with `n` dots lights, kept near the middle. */\nconst COMET_ROWS = [[], [2], [1, 2], [0, 1, 2], [0, 1, 2, 3]] as const;\n\n/** Comet: a dense head of full Braille columns thinning to single dots. */\nconst cometFrame = (frame: number, cells: number): string => {\n  const columns = cells * 2;\n  const span = columns + COMET_TAIL.length;\n  const head = frame % span;\n  let out = \"\";\n  for (let cell = 0; cell < cells; cell += 1) {\n    let mask = 0;\n    for (let side = 0; side < 2; side += 1) {\n      const behind = head - (cell * 2 + side);\n      const dots = behind >= 0 ? (COMET_TAIL[behind] ?? 0) : 0;\n      for (const row of COMET_ROWS[dots] ?? []) {\n        mask += BRAILLE_DOT_BITS[row]?.[side] ?? 0;\n      }\n    }\n    out += mask === 0 ? \" \" : brailleChar(mask);\n  }\n  return out;\n};\n\nconst glyphsAt = (\n  variant: LoaderVariant,\n  spinner: SpinnerName,\n  frame: number\n): string => {\n  switch (variant) {\n    case \"spinner\": {\n      const frames = SPINNERS[spinner];\n      return frames[frame % frames.length] ?? \" \";\n    }\n    case \"dots\": {\n      return dotsFrame(frame);\n    }\n    case \"wave\": {\n      return waveFrame(frame, TIMING.wave.cells);\n    }\n    case \"comet\": {\n      return cometFrame(frame, TIMING.comet.cells);\n    }\n    default: {\n      const exhaustive: never = variant;\n      return exhaustive;\n    }\n  }\n};\n\n/** The frame drawn when motion is off: one that reads as \"busy\" on its own. */\nconst STILL_FRAME = {\n  comet: 9,\n  dots: 1,\n  spinner: 0,\n  wave: 6,\n} as const satisfies Record<LoaderVariant, number>;\n\n/**\n * A loading indicator drawn in glyphs: a spinner from `SPINNERS`, walking\n * dots, an eighth-block wave or a Braille comet. It is a polite live\n * region, so screen readers hear `label` once; the glyphs are hidden from\n * them. The width is fixed in cells, so nothing around it shifts.\n */\nexport const Loader = ({\n  label = \"Loading\",\n  showLabel = false,\n  variant = \"spinner\",\n  spinner = \"orbit\",\n  size = \"md\",\n  color = \"ink\",\n  speed = 1,\n  cell,\n  className,\n  style,\n  ...props\n}: LoaderProps) => {\n  const glyphRef = useRef<HTMLSpanElement>(null);\n  const shown = useRef(\"\");\n  const height = cell ?? CELLS[size];\n  const { cells, rate } = TIMING[variant];\n  const still = STILL_FRAME[variant];\n  // Frames per second of motion; speed 0 holds the still frame.\n  const pace = rate * Math.max(speed, 0.01);\n\n  useFrameLoop(\n    (time) => {\n      const el = glyphRef.current;\n      if (!el) {\n        return;\n      }\n      const text = glyphsAt(variant, spinner, Math.floor(time * pace));\n      // Only touch the DOM when the glyphs change, not every tick.\n      if (text !== shown.current) {\n        shown.current = text;\n        el.textContent = text;\n      }\n    },\n    {\n      enabled: speed > 0,\n      fps: Math.min(60, Math.max(4, pace)),\n      // Halfway into the still frame, so rounding can't land on its neighbour.\n      stillTime: (still + 0.5) / pace,\n      target: glyphRef,\n    }\n  );\n\n  const glyphStyle: CSSProperties = {\n    ...SEAL,\n    color: cssColor(color),\n    fontFamily: \"var(--ascii-font, monospace)\",\n    fontSize: `${height / GLYPH_EM}px`,\n    fontVariantLigatures: \"none\",\n    letterSpacing: 0,\n    lineHeight: `${height}px`,\n    width: `${cells}ch`,\n  };\n\n  return (\n    <span\n      role=\"status\"\n      aria-live=\"polite\"\n      className={cn(\"inline-flex items-center gap-2 align-middle\", className)}\n      style={style}\n      {...props}\n    >\n      <span\n        ref={glyphRef}\n        aria-hidden=\"true\"\n        className=\"inline-block shrink-0 overflow-hidden whitespace-pre select-none\"\n        style={glyphStyle}\n      >\n        {glyphsAt(variant, spinner, still)}\n      </span>\n      <span\n        className={cn(\n          showLabel ? \"text-muted-foreground font-mono text-xs\" : \"sr-only\"\n        )}\n      >\n        {label}\n      </span>\n    </span>\n  );\n};\n"},{"path":"components/progress-bar.tsx","language":"tsx","content":"\"use client\";\n\nimport { useEffect, useId, useRef, useState } from \"react\";\nimport type { ComponentProps, CSSProperties } from \"react\";\n\nimport {\n  cssColor,\n  EIGHTHS_RIGHT,\n  eighthsBar,\n  MOTION,\n  SERIES_COLORS,\n  useFrameLoop,\n  usePrefersReducedMotion,\n} from \"@/lib/ascii\";\nimport type { AsciiColor } from \"@/lib/ascii\";\nimport { cn } from \"@/lib/utils\";\n\n/**\n * Font size per cell height for DOM glyphs. Cascadia Mono's full block and\n * box lines are 1.17em tall, so at this size blocks and lines in\n * neighbouring rows touch instead of leaving a hairline between them.\n */\nconst GLYPH_EM = 1.17;\n\n/**\n * A hairline stroke in the text colour. Adjacent block glyphs meet at\n * fractional pixels, where anti-aliasing leaves a faint seam; the stroke\n * covers it without visibly thickening the glyphs.\n */\nconst SEAL = { WebkitTextStroke: \"0.045em currentColor\" } as const;\n\nexport type ProgressBarSize = \"sm\" | \"md\" | \"lg\";\n\n/** The glyph drawn along the empty part of the track. */\nexport type ProgressTrack = \"shade\" | \"dots\" | \"line\" | \"none\";\n\n/** One part of a stacked bar, such as one file type in a storage quota. */\nexport interface ProgressPart {\n  /** Name in the legend and for screen readers. */\n  label: string;\n  /** Size of the part, in the same units as `max`. */\n  value: number;\n  /** Colour: a palette name or any CSS colour. Default: the next series colour. */\n  color?: AsciiColor;\n}\n\ninterface ProgressShared {\n  /** What is in progress. Shown above the bar and used as its accessible name. */\n  label: string;\n  /** The value that means done (or the capacity, for parts). Default 100. */\n  max?: number;\n  /** Text for the readout and screen readers. Default: the percentage. */\n  valueText?: string;\n  /** Keep the label and readout for screen readers only. Default false. */\n  hideLabel?: boolean;\n  /** Glyph cell height: `sm` 12px, `md` 16px, `lg` 20px. Default `\"md\"`. */\n  size?: ProgressBarSize;\n  /** Glyph along the empty track: `░`, `·`, `─` or nothing. Default `\"shade\"`. */\n  track?: ProgressTrack;\n  /** Colour of the fill: a palette name or any CSS colour. Default `ink`. */\n  color?: AsciiColor;\n  /** Split the bar into this many blocks a cell apart, like a step meter. Default: one continuous bar. */\n  segments?: number;\n  /** Width in cells. Default: as many whole cells as fit the container. */\n  columns?: number;\n  /** Ease between values and grow in on mount. Default true; off under reduced motion. */\n  animate?: boolean;\n  /** Glyph cell height in CSS pixels. Overrides `size`. */\n  cell?: number;\n}\n\n/** One value from 0 to `max`, or indeterminate when `value` is left out. */\nexport interface SingleProgressProps extends ProgressShared {\n  /** Progress from 0 to `max`. Leave it out (or pass null) for an indeterminate bar. */\n  value?: number | null;\n  parts?: never;\n  unit?: never;\n}\n\n/** Several parts stacked left to right, with a legend under the bar. */\nexport interface StackedProgressProps extends ProgressShared {\n  /** The parts, left to right. Their sum is the total against `max`. */\n  parts: readonly ProgressPart[];\n  /** Shown after each part's value in the legend, such as `\" GB\"`. */\n  unit?: string;\n  value?: never;\n}\n\nexport type ProgressBarProps = Omit<ComponentProps<\"div\">, \"children\"> &\n  (SingleProgressProps | StackedProgressProps);\n\nconst CELLS = { lg: 20, md: 16, sm: 12 } as const satisfies Record<\n  ProgressBarSize,\n  number\n>;\n\nconst TRACK_GLYPHS = {\n  dots: \"·\",\n  line: \"─\",\n  none: \" \",\n  shade: \"░\",\n} as const satisfies Record<ProgressTrack, string>;\n\n/** Used for the first render, before the container is measured. */\nconst FALLBACK_COLUMNS = 32;\nconst PROBE = \"0000000000\";\n/** The indeterminate comet: shaded tail, solid body, then an eighths head. */\nconst COMET_TAIL = [\"░\", \"▒\", \"▓\"] as const;\nconst COMET_BODY = 4;\nconst SWEEP_SECONDS = 1.8;\n\nconst clamp01 = (value: number) => (value > 0 ? Math.min(value, 1) : 0);\n\n/** Font size and line height that make one line of text one glyph cell tall. */\nconst cellText = (cell: number): CSSProperties => ({\n  fontFamily: \"var(--ascii-font, monospace)\",\n  fontSize: `${cell / GLYPH_EM}px`,\n  fontVariantLigatures: \"none\",\n  letterSpacing: 0,\n  lineHeight: `${cell}px`,\n  whiteSpace: \"pre\",\n});\n\n/**\n * Whole glyph cells that fit the box, from the width of a probe set in the\n * same font. The probe is observed too, so a web font that loads late or a\n * zoom change measures again.\n */\nconst useColumns = (fixed: number | undefined) => {\n  const boxRef = useRef<HTMLDivElement>(null);\n  const probeRef = useRef<HTMLSpanElement>(null);\n  const [measured, setMeasured] = useState(FALLBACK_COLUMNS);\n  useEffect(() => {\n    const box = boxRef.current;\n    const probe = probeRef.current;\n    if (fixed !== undefined || !box || !probe) {\n      return;\n    }\n    const measure = () => {\n      const advance = probe.getBoundingClientRect().width / PROBE.length;\n      // A hidden or unlaid-out box reads 0 wide: keep the last good count.\n      if (advance > 0 && box.clientWidth > 0) {\n        setMeasured(Math.max(1, Math.floor(box.clientWidth / advance + 0.01)));\n      }\n    };\n    measure();\n    const observer = new ResizeObserver(measure);\n    observer.observe(box);\n    observer.observe(probe);\n    return () => observer.disconnect();\n  }, [fixed]);\n  return {\n    boxRef,\n    columns: fixed === undefined ? measured : Math.max(1, Math.round(fixed)),\n    probeRef,\n  };\n};\n\n/**\n * `target` eased from the values shown last, so a new value slides in\n * eighth by eighth instead of jumping. Starts from zeros when `animate`.\n */\nconst useEased = (\n  target: readonly number[],\n  animate: boolean\n): readonly number[] => {\n  const reduced = usePrefersReducedMotion();\n  const live = animate && !reduced;\n  const [shown, setShown] = useState<readonly number[]>(() =>\n    live ? target.map(() => 0) : target\n  );\n  const shownRef = useRef(shown);\n  const key = target.join(\",\");\n  useEffect(() => {\n    const goal = key === \"\" ? [] : key.split(\",\").map(Number);\n    const from = shownRef.current;\n    if (!live || from.length !== goal.length) {\n      shownRef.current = goal;\n      setShown(goal);\n      return;\n    }\n    const start = performance.now();\n    let frame = 0;\n    const step = (now: number) => {\n      const t = Math.min(1, Math.max(0, (now - start) / MOTION.slow));\n      // Ease out: fast toward the new value, settling gently on it.\n      const eased = 1 - (1 - t) ** 4;\n      const next = goal.map((value, index) => {\n        const previous = from[index] ?? 0;\n        return previous + (value - previous) * eased;\n      });\n      shownRef.current = next;\n      setShown(next);\n      if (t < 1) {\n        frame = requestAnimationFrame(step);\n      }\n    };\n    frame = requestAnimationFrame(step);\n    return () => cancelAnimationFrame(frame);\n  }, [key, live]);\n  return shown;\n};\n\ninterface Layout {\n  /** For each drawn cell, whether it is part of the bar (false: a gap). */\n  readonly slots: readonly boolean[];\n  /** Number of bar cells, gaps excluded. */\n  readonly fillable: number;\n}\n\n/** The cells of the bar, cut into `segments` blocks one blank cell apart. */\nconst layoutCells = (columns: number, segments: number | undefined): Layout => {\n  const count = segments === undefined ? 1 : Math.max(1, Math.round(segments));\n  if (count < 2) {\n    return {\n      fillable: columns,\n      slots: Array.from({ length: columns }, () => true),\n    };\n  }\n  const width = Math.max(1, Math.floor((columns - (count - 1)) / count));\n  const slots: boolean[] = [];\n  for (let block = 0; block < count; block += 1) {\n    if (block > 0) {\n      slots.push(false);\n    }\n    for (let cell = 0; cell < width; cell += 1) {\n      slots.push(true);\n    }\n  }\n  return { fillable: width * count, slots };\n};\n\n/** Spread a run of glyphs, one per bar cell, over the layout's slots. */\nconst spread = (glyphs: string, layout: Layout): string => {\n  const cells = [...glyphs];\n  let next = 0;\n  return layout.slots\n    .map((slot) => {\n      if (!slot) {\n        return \" \";\n      }\n      const glyph = cells[next] ?? \" \";\n      next += 1;\n      return glyph;\n    })\n    .join(\"\");\n};\n\ninterface Run {\n  readonly text: string;\n  readonly color: AsciiColor;\n}\n\ninterface StackedPart extends ProgressPart {\n  readonly color: AsciiColor;\n  readonly share: number;\n}\n\n/** Parts with their colours and shares of `max`, clipped to the track. */\nconst stackParts = (\n  parts: readonly ProgressPart[],\n  max: number\n): StackedPart[] => {\n  let room = 1;\n  return parts.map((part, index) => {\n    const share = Math.min(room, clamp01(Math.max(0, part.value) / max));\n    room -= share;\n    return {\n      ...part,\n      color: part.color ?? SERIES_COLORS[index % SERIES_COLORS.length] ?? \"ink\",\n      share,\n    };\n  });\n};\n\n/**\n * Stacked fills as coloured runs. Part boundaries snap to whole cells (a\n * cell holds one glyph, so it can't show two colours side by side); the\n * leading edge of the total keeps its eighth-cell precision.\n */\nconst stackedRuns = (\n  shares: readonly number[],\n  colors: readonly AsciiColor[],\n  layout: Layout\n): Run[] => {\n  const total = clamp01(shares.reduce((sum, share) => sum + share, 0));\n  const edge = eighthsBar(total, layout.fillable);\n  const solidCells = Math.floor(total * layout.fillable);\n  const runs: Run[] = [];\n  let used = 0;\n  let cumulative = 0;\n  for (const [index, share] of shares.entries()) {\n    cumulative += share;\n    const last = index === shares.length - 1 || cumulative >= total - 1e-9;\n    const end = last\n      ? layout.fillable\n      : Math.min(solidCells, Math.round(cumulative * layout.fillable));\n    if (end > used) {\n      runs.push({ color: colors[index] ?? \"ink\", text: edge.slice(used, end) });\n      used = end;\n    }\n    if (last) {\n      break;\n    }\n  }\n  return runs;\n};\n\n/** Cut runs into the slots of a segmented layout, keeping their colours. */\nconst spreadRuns = (runs: readonly Run[], layout: Layout): Run[] => {\n  const flat = runs.flatMap((run) =>\n    [...run.text].map((glyph) => ({ color: run.color, glyph }))\n  );\n  const out: Run[] = [];\n  let next = 0;\n  for (const slot of layout.slots) {\n    const cell = slot ? flat[next] : undefined;\n    if (slot) {\n      next += 1;\n    }\n    const glyph = cell?.glyph ?? \" \";\n    const color = cell?.color ?? \"ink\";\n    const previous = out.at(-1);\n    if (previous && (previous.color === color || glyph === \" \")) {\n      out[out.length - 1] = {\n        color: previous.color,\n        text: previous.text + glyph,\n      };\n    } else {\n      out.push({ color, text: glyph });\n    }\n  }\n  return out;\n};\n\n/** The comet at sweep phase `t` (0 to 1) as one string of `cells` glyphs. */\nconst cometLine = (t: number, cells: number): string => {\n  const length = COMET_TAIL.length + COMET_BODY;\n  // In eighths: from the head just entering to the tail just leaving.\n  const travel = (cells + length + 1) * 8;\n  const eased = t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;\n  const head = Math.round(eased * travel);\n  const headCell = Math.floor(head / 8);\n  const glyphs: string[] = Array.from({ length: cells }, () => \" \");\n  const put = (index: number, glyph: string) => {\n    if (index >= 0 && index < cells) {\n      glyphs[index] = glyph;\n    }\n  };\n  put(headCell, EIGHTHS_RIGHT[head % 8] ?? \" \");\n  for (let offset = 1; offset <= length; offset += 1) {\n    const tail = offset - COMET_BODY - 1;\n    put(headCell - offset, tail < 0 ? \"█\" : (COMET_TAIL.at(-1 - tail) ?? \"░\"));\n  }\n  return glyphs.join(\"\");\n};\n\n/** The indeterminate fill: a comet that sweeps the track on a loop. */\nconst Comet = ({ layout, color }: { layout: Layout; color: AsciiColor }) => {\n  const ref = useRef<HTMLSpanElement>(null);\n  const draw = (time: number) => {\n    const el = ref.current;\n    if (el) {\n      const phase = (time / SWEEP_SECONDS) % 1;\n      el.textContent = spread(cometLine(phase, layout.fillable), layout);\n    }\n  };\n  // Still frame under reduced motion: the comet rests mid-track.\n  useFrameLoop(draw, { fps: 30, stillTime: SWEEP_SECONDS / 2, target: ref });\n  return (\n    <span\n      ref={ref}\n      className=\"absolute inset-0\"\n      style={{ ...SEAL, color: cssColor(color) }}\n    >\n      {spread(cometLine(0.5, layout.fillable), layout)}\n    </span>\n  );\n};\n\nconst number = new Intl.NumberFormat(\"en\", { maximumFractionDigits: 1 });\n\n/** Aria value props for a determinate or indeterminate bar. */\nconst ariaValues = ({\n  determinate,\n  current,\n  max,\n  readout,\n  valueText,\n}: {\n  determinate: boolean;\n  current: number;\n  max: number;\n  readout: string;\n  valueText: string | undefined;\n}) =>\n  determinate\n    ? {\n        \"aria-valuemax\": max,\n        \"aria-valuemin\": 0,\n        \"aria-valuenow\": current,\n        \"aria-valuetext\": readout,\n      }\n    : { \"aria-valuetext\": valueText };\n\n/** What the fill eases toward: one share per part, the ratio, or nothing. */\nconst targetShares = (\n  stacked: readonly StackedPart[] | null,\n  determinate: boolean,\n  ratio: number\n): number[] => {\n  if (stacked !== null) {\n    return stacked.map((part) => part.share);\n  }\n  return determinate ? [ratio] : [];\n};\n\n/** The fill as coloured runs, from the shares shown right now. */\nconst fillRuns = ({\n  stacked,\n  shares,\n  color,\n  layout,\n}: {\n  stacked: readonly StackedPart[] | null;\n  shares: readonly number[];\n  color: AsciiColor;\n  layout: Layout;\n}): Run[] => {\n  if (stacked !== null) {\n    const colors = stacked.map((part) => part.color);\n    return spreadRuns(stackedRuns(shares, colors, layout), layout);\n  }\n  if (shares.length === 0) {\n    return [];\n  }\n  const text = spread(eighthsBar(shares[0] ?? 0, layout.fillable), layout);\n  return [{ color, text }];\n};\n\n/** `█` swatch, label and value for each part, under a stacked bar. */\nconst Legend = ({\n  parts,\n  unit,\n}: {\n  parts: readonly StackedPart[];\n  unit: string;\n}) => (\n  <ul className=\"flex flex-wrap gap-x-4 gap-y-1\">\n    {parts.map((part) => (\n      <li\n        key={part.label}\n        className=\"text-muted-foreground flex items-baseline gap-1.5 text-xs\"\n      >\n        <span\n          aria-hidden=\"true\"\n          className=\"font-mono\"\n          style={{ color: cssColor(part.color) }}\n        >\n          █\n        </span>\n        <span className=\"text-foreground\">{part.label}</span>\n        <span className=\"font-mono tabular-nums\">\n          {`${number.format(part.value)}${unit}`}\n        </span>\n      </li>\n    ))}\n  </ul>\n);\n\n/**\n * A progress bar drawn in glyphs. The fill is eighth blocks (`▏▎▍▌▋▊▉█`),\n * so the value is exact to an eighth of a cell, over a track of `░`, `·`\n * or `─`. Without a `value`, a comet of shaded glyphs sweeps the track.\n * `parts` stacks several values in their own colours with a legend, and\n * `segments` cuts the bar into blocks for step meters.\n */\nexport const ProgressBar = ({\n  label,\n  value,\n  parts,\n  unit = \"\",\n  max = 100,\n  valueText,\n  hideLabel = false,\n  size = \"md\",\n  track = \"shade\",\n  color = \"ink\",\n  segments,\n  columns: fixedColumns,\n  animate = true,\n  cell,\n  className,\n  style,\n  ...props\n}: ProgressBarProps) => {\n  const labelId = useId();\n  const limit = Math.max(max, 1e-9);\n  const stacked = parts === undefined ? null : stackParts(parts, limit);\n  const total =\n    parts === undefined\n      ? (value ?? 0)\n      : parts.reduce((sum, part) => sum + Math.max(0, part.value), 0);\n  const determinate = stacked !== null || typeof value === \"number\";\n  const ratio = clamp01(total / limit);\n  const readout = valueText ?? `${Math.round(ratio * 100)}%`;\n  const height = cell ?? CELLS[size];\n\n  const { boxRef, probeRef, columns } = useColumns(fixedColumns);\n  const layout = layoutCells(columns, segments);\n  const width = layout.slots.length;\n  const shares = useEased(targetShares(stacked, determinate, ratio), animate);\n  const fill = fillRuns({ color, layout, shares, stacked });\n  const trackGlyph = TRACK_GLYPHS[track];\n  const trackColor = cssColor(stacked === null ? color : \"grey\");\n\n  return (\n    <div\n      role=\"progressbar\"\n      aria-labelledby={labelId}\n      {...ariaValues({\n        current: Math.min(max, Math.max(0, total)),\n        determinate,\n        max,\n        readout,\n        valueText,\n      })}\n      className={cn(\"flex w-full min-w-0 flex-col gap-2\", className)}\n      style={style}\n      {...props}\n    >\n      <div\n        className={cn(\n          \"flex items-baseline justify-between gap-4 text-sm\",\n          hideLabel && \"sr-only\"\n        )}\n      >\n        <span id={labelId} className=\"text-foreground min-w-0 truncate\">\n          {label}\n        </span>\n        {determinate || valueText ? (\n          <span\n            aria-hidden=\"true\"\n            className=\"text-muted-foreground shrink-0 font-mono text-xs tabular-nums\"\n          >\n            {readout}\n          </span>\n        ) : null}\n      </div>\n      <div ref={boxRef} aria-hidden=\"true\" className=\"relative w-full min-w-0\">\n        <span\n          ref={probeRef}\n          className=\"invisible absolute top-0 left-0\"\n          style={cellText(height)}\n        >\n          {PROBE}\n        </span>\n        <div\n          className=\"relative overflow-hidden select-none\"\n          style={{ ...cellText(height), width: `${width}ch` }}\n        >\n          <span\n            className=\"block\"\n            style={{\n              color: `color-mix(in oklab, ${trackColor} 50%, transparent)`,\n            }}\n          >\n            {spread(trackGlyph.repeat(layout.fillable), layout)}\n          </span>\n          {determinate ? (\n            <span className=\"absolute inset-0\" style={SEAL}>\n              {fill.map((run, index) => (\n                <span\n                  // Runs are positional: the nth run of the bar.\n                  // oxlint-disable-next-line react/no-array-index-key\n                  key={index}\n                  style={{ color: cssColor(run.color) }}\n                >\n                  {run.text}\n                </span>\n              ))}\n            </span>\n          ) : (\n            <Comet layout={layout} color={color} />\n          )}\n        </div>\n      </div>\n      {stacked === null ? null : <Legend parts={stacked} unit={unit} />}\n    </div>\n  );\n};\n"}],"prompt":""};
